css:
/* THEME 9: DARK BRUTALIST WIREFRAME */
@import url('https://fonts.googleapis.com/css2?family=Chivo+Mono:wght@400;600;800&family=Cabinet+Grotesk:wght@800;900&display=swap');

:root {
  --bg-main: #121212;
  --bg-card: #181818;
  --bg-header: #121212;
  --accent: #ff5500;
  --text-main: #f0f0f0;
  --text-gray: #888888;
  --border-color: #333333;
  --font-main: 'Chivo Mono', monospace;
  --font-heading: 'Cabinet Grotesk', sans-serif;
  --shadow-sm: none;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

body { 
  font-family: var(--font-main); 
  background-color: var(--bg-main); 
  color: var(--text-gray); 
  line-height: 1.6; 
  display: flex; flex-direction: column; min-height: 100vh; 
}

a { text-decoration: none; color: inherit; }
a:hover { color: var(--accent); }

h1, h2, h3, h4 { color: var(--text-main); font-family: var(--font-heading); font-weight: 900; text-transform: uppercase; }

.container { max-width: 1300px; margin: 0 auto; padding: 0 25px; width: 100%; }

.site-header { 
  background: var(--bg-header); 
  border-bottom: 2px dashed var(--border-color); 
  position: sticky; top: 0; z-index: 100;
}
.header-top { display: flex; justify-content: space-between; align-items: center; padding: 20px 25px; max-width: 1300px; margin: 0 auto; }
.logo { font-size: 2rem; font-family: var(--font-heading); font-weight: 900; color: var(--accent); letter-spacing: 1px; }

.header-nav { border-bottom: 2px solid var(--border-color); background: #161616; }
.nav-links { display: flex; justify-content: space-between; gap: 10px; padding: 10px 20px; overflow-x: auto; }
.nav-links a { color: var(--text-main); font-size: 0.8rem; font-weight: 600; text-transform: uppercase; border: 1px solid var(--border-color); padding: 4px 10px; }
.nav-links a:hover { background: var(--accent); color: #000; border-color: var(--accent); }

.bottom-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(320px, 1fr)); gap: 20px; margin: 50px 0; }

.post-thumb-card { 
  background: var(--bg-card); 
  border: 1px solid var(--border-color); 
  display: flex; flex-direction: column; justify-content: space-between; 
  padding: 25px; position: relative; 
  min-height: 250px; 
}
.post-thumb-card::before { content: '+'; position: absolute; top: -6px; left: -6px; color: var(--border-color); font-size: 12px; }
.post-thumb-card:hover { border: 1px solid var(--accent); }

.cat-badge { 
  background: #222; color: var(--accent); 
  border-left: 3px solid var(--accent); 
  padding: 3px 8px; font-size: 0.7rem; font-weight: 600; 
  display: inline-block; margin-bottom: 15px; width: fit-content; text-transform: uppercase; 
}

.post-thumb-title { color: var(--text-main); font-size: 1.3rem; line-height: 1.25; font-family: var(--font-heading); }

.post-container { max-width: 860px; margin: 50px auto; background: var(--bg-card); padding: 45px; border: 2px solid var(--border-color); }
.post-h1 { font-size: 3.5rem; line-height: 1.05; margin-bottom: 20px; }
.post-meta-info { display: flex; align-items: center; gap: 15px; border-top: 1px dashed var(--border-color); border-bottom: 1px dashed var(--border-color); padding: 15px 0; margin-bottom: 30px; font-size: 0.85rem; }
.post-meta-info img { width: 40px; height: 40px; border-radius: 0; border: 1px solid var(--accent); }
.post-content { font-size: 1.05rem; line-height: 1.8; color: #bbb; }
.post-content h2 { font-size: 1.8rem; margin: 40px 0 15px; color: var(--accent); }
.post-content p { margin-bottom: 20px; }
.post-content a { color: var(--accent); text-decoration: underline; }

.pagination { display: flex; justify-content: center; gap: 8px; margin: 30px 0 70px; }
.page-link { width: 38px; height: 38px; display: flex; justify-content: center; align-items: center; border: 1px solid var(--border-color); background: var(--bg-card); font-weight: 600; font-size: 0.9rem; }
.page-link:hover { border-color: var(--accent); color: var(--accent); }
.page-link.active { background: var(--accent); color: #000; border-color: var(--accent); }

.site-footer { background: #0c0c0c; border-top: 2px dashed var(--border-color); padding: 60px 0 25px; margin-top: auto; }
.footer-container { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 40px; max-width: 1300px; margin: 0 auto; padding: 0 25px; }
.footer-title { margin-bottom: 15px; font-size: 1rem; color: var(--text-main); }
.footer-bottom { text-align: center; margin-top: 50px; padding-top: 20px; border-top: 1px solid #222; font-size: 0.75rem; color: #555; }
